        { "Security_Migrate_Kdf_Body", "资料库使用旧版加密参数（PBKDF2 100,000 次迭代）。新版默认 3,000,000 次，可大幅提高暴力破解成本。升级将重新加密资料库（约 1 秒）。升级后，5.2.0 及更早版本将无法打开此资料库（桌面便签、MCP 接口、备份文件不受影响）。升级后，解锁资料库会产生可感知的等待时间，低配设备延迟更高。确认升级？" },
        { "Security_Migrate_V5_Title", "升级数据加密" },
        { "Security_Migrate_V5_Body", "资料库使用旧版加密参数（PBKDF2）。本次升级改为 Argon2id（内存硬化，大幅提高暴力破解成本），并为加密头增加完整性校验与参数绑定。升级将重新加密资料库（Argon2id 计算约 1 秒，低配设备更久）。升级后，10.3 及更早版本将无法打开此资料库（数据不会损坏，重新安装新版即可读取；桌面便签、MCP 接口、备份文件不受影响）。确认升级？" },
