        { "Setting_Mcp_Copy_Desc", "本页提供两种复制方式，请根据你的使用场景选择：\n\n· 「JSON」：复制标准的 MCP 服务器配置（JSON 格式，访问令牌已自动填入）。适合熟悉 MCP 配置的用户——复制后手动粘贴到你所使用 Agent 的配置文件中（如 Claude Desktop 的 claude_desktop_config.json、Cursor 的 mcp.json）即可生效。\n\n· 「提示词」：复制一段完整的「配置说明 + JSON」，其中包含 Novara 的介绍、配置步骤、生效方式与注意事项。适合不熟悉配置、或希望由 Agent 代劳的用户——复制后直接发送给你的 Agent，它会自动识别你的运行环境并完成配置。" },
