        { "Setting_Mcp_DeleteConfirm_Message", "开启后 Agent 有权限删除已有条目，删除会进入回收站，可随时恢复。确定开启吗？" },
        { "Setting_Mcp_DeleteConfirm_Hint", "提示：开启后，还需在 MCP 配置中打开各客户端的「权限」面板并勾选「删除」列，删除权限才会实际生效。" },
        { "Setting_Mcp_DeleteConfirm_Ok", "开启" },
        { "Setting_Mcp_Hint", "请帮我把本地应用 Novara 配置为 MCP（Model Context Protocol）服务器。\n\n【Novara 是什么】\nNovara 是本机个人知识管理应用，通过 MCP 暴露 16 个工具（前缀 mcp__novara__），管理备忘、待办、便签、日记/文档、路径备份五类数据。\n\n【配置内容】\n下面这段是标准的 MCP 服务器配置，请合并进我所用 Agent/客户端的 MCP 配置文件：\n\n{JSON}\n\n【请按步骤操作】\n1. 识别我当前使用的 Agent/客户端（Claude Desktop / Cursor / VS Code / Codex / DeepSeek Harness 等），不确定就问我。\n2. 找到它的 MCP 配置文件（如 Claude Desktop 的 claude_desktop_config.json、Cursor 的 mcp.json），把上面配置合并进去，保持 JSON 合法。\n3. 让我重启或重载客户端使配置生效，然后请新开一个对话——工具列表在会话启动时定格，本对话里看不到新工具，必须换新对话验证。\n4. 在新对话里确认能看到 mcp__novara__ 开头的工具，先调用 mcp__novara__get_auth_status 查看当前授权范围，再调用 mcp__novara__list_items 做一次只读验证并告诉我结果。\n\n【注意】\n- 配置里的 token 是访问凭证，原样填入，不要修改或外传；也不要把它回显到对话、日志、报告里。\n- 下面这些操作会降低安全限制（点允许 / 开接口 / 解锁隐私锁 / 重置 Key），请你提醒我本人在确认是 Novara 应用后完成，不要让 AI 代为执行。\n- 若提示「未授权」：请我本人打开 Novara 在弹窗点「允许」。\n- 若提示「MCP 接口已关闭」：请我本人去 Novara 设置页开启。\n- 若提示「数据库未解锁」：请我本人打开 Novara 输入隐私锁密码解锁后再试。\n- 若提示「访问令牌无效」：请我本人在 Novara 设置页「MCP 接口」卡片里重新生成配置或重置 Key，并由我亲手写回配置文件——密钥不经过对话。\n- 若提示「配置已写入但未生效」：工具列表未刷新，让我重启客户端并新开一个对话再试。\n- 若提示「权限不足」：这是部分工具/类型未授权（错误信息会列出缺失项与已授权清单），请我本人去 Novara 设置的 MCP 授权面板勾选所需权限。\n\n配置写好后：列出需要我本人做的 UI 操作（重载 / 点允许 / 勾权限等），我完成后你再新开对话跑一次只读验证并报告结果。" },
        { "Setting_Mcp_ExeNotFound", "未能在本地定位到 NovaraMCP.exe（下方配置的 command 为空）。请确认已从源码构建过 NovaraMCP，或把 command 手动改成实际的 NovaraMCP.exe 完整路径。" },
