        { "Carousel_P1_Title", "Switch tabs with one click" },
        { "Carousel_P1_Memo", "Store accounts, passwords and API keys with grouping and one-click per-field copy. Built-in 3-level API key checks - connectivity probe, status diagnosis, relay probe - with auto protocol detection and check history" },
        { "Carousel_P1_Path", "Bookmark frequently used file and folder paths: reachability is checked automatically and file attributes (size, created/modified time, read-only, hidden) are shown. Copy the path, open the file or its folder, or drag entries in from the desktop" },
        { "Carousel_P1_Plan", "Two card types - todos with checkable sub-items and quick-note cards. Both support reminders and can be sent to the desktop as stickies; content syncs from the app to the card, check states sync both ways" },
        { "Carousel_P1_Diary", "Rich-text diaries and Markdown documents. The MD document is a full Markdown editor with three views - write, split-screen compare, live preview - plus a draggable divider and row-following preview" },
        { "Carousel_P2_Title", "Everything at your fingertips" },
        { "Carousel_P2_Desc", "On the left, the edge-handle demo; on the right, a few everyday shortcuts - all of them customizable in Settings" },
