        { "Carousel_Hotkey_Search_Desc", "Global search, from any page" },
        { "Carousel_Hotkey_Capture_Desc", "Jot down a memo, todo or note in a flash" },
        { "Carousel_Hotkey_Lock_Desc", "Lock now - data turns to ciphertext instantly" },
        { "Carousel_Hotkey_More", "All of these shortcuts can be viewed and changed in Settings" },
        { "Carousel_P3_Body", "We recommend turning the privacy lock on: the library is encrypted with AES-256-GCM and stored as ciphertext while locked; it supports a lock password and Windows Hello, and can lock itself automatically on idle, on system lock, or on demand." },
        { "Carousel_P4_Title", "Plug your AI into Novara" },
        { "Carousel_P4_B1", "1. Who it fits: if you run a local AI agent, it can read, write and search your Novara data within the permissions you grant." },
        { "Carousel_P4_B2", "2. Who does not need it: if you never use AI tools, leave it off - it is off by default and nothing else changes." },
        { "Carousel_P4_B3", "3. How to enable: Settings - MCP Interface - flip the master switch, then add your agent client and its permissions." },
        { "Carousel_P5_Title", "Interconnect: snapshots and sync" },
        { "Carousel_P5_SnapDesc", "Pack the library into an encrypted self-contained web page, openable offline anytime" },
        { "Carousel_P5_SyncDesc", "End-to-end encrypted sync across devices, relayed only by your own server" },
        { "Carousel_P5_Body", "Docker one-click deployment is supported - novara.xin carries the full step-by-step guide; self-hosting means your data never touches a third party." },
        { "Carousel_P6_B1", "Thank you for using Novara" },
        { "Carousel_P6_B2", "If it serves you well, a Star on GitHub means the world to independent development" },
        { "Carousel_P6_B3", "Novara iterates frequently: found a problem? Write us an email - we fix fast and ship hotfixes; you can also check for updates anytime in Settings - Check for Updates." },
        { "Carousel_P6_GitHub", "GitHub - Star Novara" },
        { "Carousel_Seal_Title", "Novara Space" },
        { "Carousel_Seal_B1_Title", "Drop means move" },
        { "Carousel_Seal_B1_Body", "The moment a file goes in, the original is deleted from where it was - no Recycle Bin, no second copy." },
        { "Carousel_Seal_B2_Title", "Sealed means unseen" },
        { "Carousel_Seal_B2_Body", "Nothing inside gets a thumbnail, a preview or a decode. Taking it out is the only way back to the file." },
        { "Carousel_Seal_B3_Title", "Capsules open on time" },
        { "Carousel_Seal_B3_Body", "Pick anywhere from 1 minute to 40 years; until then there is no way to take it out early." },
        { "Carousel_Seal_B4_Title", "A password of its own" },
