        { "Seal_About_Body", "Novara Space encrypts your files into a separate folder on this device: once sealed, the original is deleted from where it was and does not go to the Recycle Bin. Nobody can take a time capsule out before its deadline. The password belongs to you alone and cannot be recovered if forgotten - keep it somewhere safe, not only in your head." },
