        { "Seal_Exp_BackupPrefix", "Novara_Backup" },
        { "Setting_EncExport_SealDesc", "The backup including Novara Space has been saved. Keep both passwords safe: the backup password opens the library, the Novara Space password opens the entries inside; neither has a recovery path. If the privacy-lock password was used as the backup password, that is the one which opens it." },
        { "Seal_Exp_Title", "Export Novara Space" },
        { "Seal_Exp_Body", "Exports every entry in Novara Space as one encrypted package. Nothing is decrypted and nothing inside the space is changed." },
