        { "Security_Migrate_Title", "Upgrade encryption format" },
        { "Security_Migrate_Body", "This will upgrade the database to the new AES-256-GCM encryption format. After the upgrade, the database can only be opened with Novara 3.0 or newer. Uninstalling back to 2.0 will make all data unreadable. Upgrade now?" },
        { "Security_Migrate_Confirm", "Upgrade" },
        { "Security_Migrate_Kdf_Title", "Upgrade Encryption Strength" },
        { "Security_Migrate_Kdf_Body", "This database still uses the legacy encryption parameters (PBKDF2, 100,000 iterations). The new default is 3,000,000 iterations, which greatly raises the cost of brute-force attacks. Upgrading re-encrypts the database (about 1 second). After upgrading, 5.2.0 and earlier versions cannot open this database (desktop sticky notes, the MCP interface and backup files are unaffected). Unlocking the database will produce a noticeable wait; low-end devices will see longer delays. Upgrade now?" },
        { "Security_Migrate_V5_Title", "Upgrade Database Encryption" },
        { "Security_Migrate_V5_Body", "This database still uses the legacy encryption parameters (PBKDF2). This upgrade moves to Argon2id (memory-hardened, greatly raising the cost of brute-force attacks) and adds integrity verification plus parameter binding to the database header. Upgrading re-encrypts the database (the Argon2id computation takes about 1 second; longer on low-end devices). After upgrading, 10.3 and earlier versions cannot open this database (the data is NOT damaged — reinstalling the new version makes it readable again; desktop sticky notes, the MCP interface and backup files are unaffected). Upgrade now?" },
        { "Security_Migrate_Failed", "Encryption upgrade failed. Your data is unchanged; it will retry on the next launch." },
        { "Security_Migrate_Later", "Not now" },
        { "Security_Migrate_Entry", "Upgrade encryption format" },
        { "Store_Err_DecryptFail", "Decryption failed (file is corrupted or tampered)" },
