        { "Setting_Mcp_Reset_Title", "Reset Key" },
        { "Setting_Mcp_Reset_Message", "Resetting generates a new Key; the old Key becomes invalid immediately. Configured agents must update to the new Key (reconfigure), but do not need to be re-authorized. Reset?" },
        { "Setting_Mcp_Reset_Confirm", "Reset" },
        { "Setting_Mcp_Copy_Title", "Copy JSON" },
        { "Setting_Mcp_Copy_Desc", "Two copy options are available:\n\n· \"JSON\": copies the standard MCP server configuration (JSON with the access token already filled in). For users familiar with MCP — paste it into your agent's config file (e.g. claude_desktop_config.json for Claude Desktop, mcp.json for Cursor) and it takes effect.\n\n· \"Instructions\": copies a complete configuration guide plus JSON, covering what Novara is, the setup steps, how to activate it, and important notes. For users who prefer the agent to handle it — send it directly to your agent and it will detect your environment and configure automatically." },
        { "Setting_Mcp_Copy_Hint_Short", "Instructions" },
        { "Setting_Mcp_DeleteConfirm_Title", "Delete Permission" },
        { "Setting_Mcp_DeleteConfirm_Message", "When enabled, the agent can delete existing items. Deleted items go to Trash and can be restored. Enable?" },
        { "Setting_Mcp_DeleteConfirm_Hint", "Note: after enabling, open each client's Permissions panel in MCP settings and tick the Delete column — delete permissions only take effect then." },
        { "Setting_Mcp_DeleteConfirm_Ok", "Enable" },
        { "Setting_Mcp_Hint", "Please help me configure the local app Novara as an MCP (Model Context Protocol) server.\n\n【What Novara is】\nNovara is a local personal knowledge-management app that exposes 16 tools over MCP (prefixed with mcp__novara__) for managing five kinds of data: memos, todos, notes, diaries/documents, and path backups.\n\n【Configuration】\nBelow is the standard MCP server configuration. Please merge it into the MCP config file of the agent/client I use:\n\n{JSON}\n\n【Steps】\n1. Identify the agent/client I am using (Claude Desktop / Cursor / VS Code / Codex / DeepSeek Harness, etc.). If unsure, ask me.\n2. Locate its MCP config file (e.g. claude_desktop_config.json for Claude Desktop, mcp.json for Cursor), merge the config above into it, and keep the JSON valid.\n3. Restart or reload the client so the config takes effect, then start a NEW conversation - the tool list is frozen at session start, so the new tools cannot appear in this conversation and verification must happen in a fresh one.\n4. In the new conversation, confirm you can see tools starting with mcp__novara__, call mcp__novara__get_auth_status first to see the granted scope, then call mcp__novara__list_items once as a read-only check and report the result.\n\n【Notes】\n- The token in the config is an access credential; keep it unchanged, do not share it, and never echo the key into conversations, logs or reports.\n- The actions below lower security (clicking Allow / enabling the interface / unlocking the privacy lock / resetting the Key): remind me to do them myself in Novara after confirming it is the real app - never do them for me.\n- If it says \"unauthorized\": I will open Novara and click \"Allow\" in the prompt myself.\n- If it says \"MCP interface is disabled\": I will enable it in Novara's settings myself.\n- If it says \"database is locked\": I will open Novara and unlock it with the privacy-lock password myself.\n- If it says \"invalid access token\": I will regenerate the config or reset the Key in Novara's Settings > \"MCP interface\" card myself and write it back to the config file by hand - the key must not pass through the conversation.\n- If it says \"config written but not effective\": the tool list has not refreshed - I will restart the client and start a new conversation.\n- If it says \"insufficient permission\": some tools/types are not authorized (the error lists the missing items and the granted ones); I will tick the needed permissions in the Novara settings MCP panel myself.\n\nAfter writing the config: list the UI actions I need to do myself (reload / click Allow / tick permissions, etc.); once I confirm they are done, open a NEW conversation, run one read-only verification and report the result." },
        { "Setting_Mcp_ExeNotFound", "Could not locate NovaraMCP.exe on this machine (the command below is empty). Build NovaraMCP from source, or set command to the full path of the actual NovaraMCP.exe manually." },
