        { "Carousel_P1_Plan", "待辦與便簽兩種卡片：待辦含子項勾選清單，便簽隨手速記。兩者皆可設定提醒，也能一鍵傳送到桌面便簽；內容隨編輯同步到桌面，勾選狀態雙向同步" },
        { "Carousel_P1_Diary", "富文字日記與 Markdown 文件兩種體裁。MD 文件是成熟的 Markdown 編輯器：純編輯、分屏對照、純預覽三種檢視，分割線可拖曳，預覽隨行定位" },
        { "Carousel_P2_Title", "隨手呼出，收放自如" },
        { "Carousel_P2_Desc", "左邊是邊緣把手的呼出演示，右邊是幾個常用快捷鍵；按鍵都可以在設定中自訂" },
        { "Carousel_P3_Title", "你的資料，只屬於你" },
        { "Carousel_Next", "下一步" },
        { "Carousel_Begin", "開始使用" },
        { "Carousel_Skip", "略過導覽" },
        { "Carousel_Hotkey_Search_Desc", "全域搜尋，任何頁面隨手呼出" },
        { "Carousel_Hotkey_Capture_Desc", "隨手記一條備忘、待辦或便簽" },
        { "Carousel_Hotkey_Lock_Desc", "立即鎖定，資料即刻轉為密文" },
        { "Carousel_Hotkey_More", "以上快捷鍵都可以在設定中查看與自訂" },
        { "Carousel_P3_Body", "建議開啟隱私鎖：開啟後資料庫以 AES-256-GCM 全盤加密，鎖上時資料以密文落盤；支援鎖屏密碼與 Windows Hello，還可以在閒置、系統鎖屏或手動三種時機自動上鎖。" },
        { "Carousel_P4_Title", "把你的 AI 接進 Novara" },
        { "Carousel_P4_B1", "① 適合誰：在本地使用 AI Agent 的用戶——Agent 可以在你授權的範圍內直接讀寫與檢索 Novara 資料。" },
        { "Carousel_P4_B2", "② 誰不需要：完全不用 AI 工具的話就不需要開啟；它預設關閉，不開對任何功能都沒有影響。" },
        { "Carousel_P4_B3", "③ 怎麼開啟：設定頁 →「MCP 介面」→ 打開總開關，並在設定中新增你的 Agent 用戶端與權限。" },
        { "Carousel_P5_Title", "互聯：快照與同步" },
        { "Carousel_P5_SnapDesc", "把資料庫打包成一個加密的自包含網頁，離線也能隨時打開查看" },
        { "Carousel_P5_SyncDesc", "多台裝置端對端加密同步，資料只經你自己的伺服器中轉" },
        { "Carousel_P5_Body", "支援 Docker 一鍵部署——官網 novara.xin 有完整的圖文教學，自託管全程無需把資料交給任何第三方。" },
        { "Carousel_P6_B1", "感謝使用 Novara" },
        { "Carousel_P6_B2", "如果它稱手好用，歡迎去 GitHub 點一個 Star——這對獨立開發是最大的鼓勵" },
        { "Carousel_P6_B3", "Novara 保持高頻迭代：使用中遇到任何問題，歡迎透過信箱回報，我們會及時修復並發布熱修復版本；更新也可以隨時在「設定 → 檢查更新」中手動檢查。" },
        { "Carousel_P6_GitHub", "GitHub · 給 Novara 點一個 Star" },
        { "Carousel_Seal_Title", "Novara Space" },
        { "Carousel_Seal_B1_Title", "拖入即剪下" },
        { "Carousel_Seal_B1_Body", "檔案拖進去的那一刻，原件就從原位置刪除——不經過資源回收筒，也不留副本。" },
        { "Carousel_Seal_B2_Title", "封存期不可預覽" },
        { "Carousel_Seal_B2_Body", "箱內內容不產生縮圖、不解碼、不提供預覽；取出是拿回檔案的唯一出路。" },
        { "Carousel_Seal_B3_Title", "膠囊到期才開" },
        { "Carousel_Seal_B3_Body", "時間膠囊可選 1 分鐘到 40 年，期限到來前沒有任何提前取出的入口。" },
        { "Carousel_Seal_B4_Title", "一把獨立的密碼" },
