        { "Security_Migrate_Title", "升級資料加密格式" },
        { "Security_Migrate_Body", "本次將升級至全新 AES-256-GCM 加密格式，升級完成後該資料庫僅能使用 Novara 3.0 及更高版本開啟，若卸載換回 2.0 舊版將無法讀取所有資料，確認升級？" },
        { "Security_Migrate_Confirm", "確認升級" },
        { "Security_Migrate_Kdf_Title", "升級加密強度" },
        { "Security_Migrate_Kdf_Body", "資料庫使用舊版加密參數（PBKDF2 100,000 次迭代）。新版預設 3,000,000 次，可大幅提高暴力破解成本。升級將重新加密資料庫（約 1 秒）。升級後，5.2.0 及更早版本將無法開啟此資料庫（桌面便籤、MCP 介面、備份檔案不受影響）。升級後，解鎖資料庫會產生可感知的等待時間，低配裝置延遲更高。確認升級？" },
        { "Security_Migrate_V5_Title", "升級資料加密" },
        { "Security_Migrate_V5_Body", "資料庫使用舊版加密參數（PBKDF2）。本次升級改為 Argon2id（記憶體硬化，大幅提高暴力破解成本），並為加密頭增加完整性校驗與參數綁定。升級將重新加密資料庫（Argon2id 計算約 1 秒，低配裝置更久）。升級後，10.3 及更早版本將無法開啟此資料庫（資料不會損壞，重新安裝新版即可讀取；桌面便籤、MCP 介面、備份檔案不受影響）。確認升級？" },
