        { "Setting_Mcp_Copy_Desc", "本頁提供兩種複製方式，請根據你的使用情境選擇：\n\n· 「JSON」：複製標準的 MCP 伺服器設定（JSON 格式，存取權杖已自動填入）。適合熟悉 MCP 設定的使用者——複製後手動貼上到你所使用 Agent 的設定檔中（如 Claude Desktop 的 claude_desktop_config.json、Cursor 的 mcp.json）即可生效。\n\n· 「提示詞」：複製一段完整的「設定說明 + JSON」，其中包含 Novara 的介紹、設定步驟、生效方式與注意事項。適合不熟悉設定、或希望由 Agent 代勞的使用者——複製後直接傳送給你的 Agent，它會自動識別你的執行環境並完成設定。" },
