        { "Setting_Mcp_DeleteConfirm_Hint", "提示：開啟後，還需在 MCP 設定中開啟各客戶端的「權限」面板並勾選「刪除」欄，刪除權限才會實際生效。" },
        { "Setting_Mcp_DeleteConfirm_Ok", "開啟" },
        { "Setting_Mcp_Hint", "請幫我把本機應用 Novara 設定為 MCP（Model Context Protocol）伺服器。\n\n【Novara 是什麼】\nNovara 是本機個人知識管理應用，透過 MCP 暴露 16 個工具（前綴 mcp__novara__），管理備忘、待辦、便簽、日記/文件、路徑備份五類資料。\n\n【設定內容】\n下面這段是標準的 MCP 伺服器設定，請合併進我所用 Agent/用戶端的 MCP 設定檔：\n\n{JSON}\n\n【請按步驟操作】\n1. 識別我目前使用的 Agent/用戶端（Claude Desktop / Cursor / VS Code / Codex / DeepSeek Harness 等），不確定就問我。\n2. 找到它的 MCP 設定檔（如 Claude Desktop 的 claude_desktop_config.json、Cursor 的 mcp.json），把上面設定合併進去，保持 JSON 合法。\n3. 讓我重啟或重載用戶端使設定生效，然後請新開一個對話——工具清單在會話啟動時定格，本對話裡看不到新工具，必須換新對話驗證。\n4. 在新對話裡確認能看到 mcp__novara__ 開頭的工具，先呼叫 mcp__novara__get_auth_status 查看當前授權範圍，再呼叫 mcp__novara__list_items 做一次唯讀驗證並告訴我結果。\n\n【注意】\n- 設定裡的 token 是存取憑證，原樣填入，不要修改或外傳；也不要把它回顯到對話、日誌、報告裡。\n- 下面這些操作會降低安全限制（點允許 / 開介面 / 解鎖隱私鎖 / 重設 Key），請你提醒我本人在確認是 Novara 應用後完成，不要讓 AI 代為執行。\n- 若提示「未授權」：請我本人打開 Novara 在彈窗點「允許」。\n- 若提示「MCP 介面已關閉」：請我本人去 Novara 設定頁開啟。\n- 若提示「資料庫未解鎖」：請我本人打開 Novara 輸入隱私鎖密碼解鎖後再試。\n- 若提示「存取權杖無效」：請我本人在 Novara 設定頁「MCP 介面」卡片裡重新產生設定或重設 Key，並由我親手寫回設定檔——金鑰不經過對話。\n- 若提示「設定已寫入但未生效」：工具清單未刷新，讓我重啟用戶端並新開一個對話再試。\n- 若提示「權限不足」：這是部分工具/類型未授權（錯誤資訊會列出缺失項與已授權清單），請我本人去 Novara 設定的 MCP 授權面板勾選所需權限。\n\n設定寫好後：列出需要我本人做的 UI 操作（重載 / 點允許 / 勾權限等），我完成後你再新開對話跑一次唯讀驗證並報告結果。" },
        { "Setting_Mcp_ExeNotFound", "未能在本機定位到 NovaraMCP.exe（下方設定的 command 為空）。請確認已從原始碼建置過 NovaraMCP，或把 command 手動改成實際的 NovaraMCP.exe 完整路徑。" },
