        { "Lock_Forgot_Warning", "Novara 보안 구조에는 비밀번호 복구, 키 해독, 백도어 우회 메커니즘이 없습니다. 접근 키를 분실하면 기존 암호화 데이터베이스를 해독할 수 없습니다. 확인 버튼을 누르면 이 컴퓨터의 모든 저장 데이터가 영구히 삭제되고, 암호화 데이터베이스가 파기된 후 빈 초기화 파일이 새로 생성됩니다. 모든 기록과 사용자 설정은 한 번 삭제되면 복구할 수 없습니다. 전체 데이터 삭제 및 데이터베이스 재설정을 실행하시겠습니까? 참고: 스페이스가 활성화되어 있어도 영향을 받지 않으며 자체 비밀번호로 계속 들어갈 수 있습니다." },
