        { "Lock_Password_Placeholder", "비밀번호를 입력하세요" },
        { "Security_Migrate_Title", "데이터 암호화 형식 업그레이드" },
        { "Security_Migrate_Body", "새 AES-256-GCM 암호화 형식으로 업그레이드됩니다. 업그레이드 후 이 데이터베이스는 Novara 3.0 이상에서만 열 수 있으며, 2.0으로 되돌리면 모든 데이터를 읽을 수 없게 됩니다. 업그레이드하시겠습니까?" },
        { "Security_Migrate_Confirm", "업그레이드" },
        { "Security_Migrate_Kdf_Title", "암호화 강도 업그레이드" },
        { "Security_Migrate_Kdf_Body", "이 데이터베이스는 이전 암호화 매개변수(PBKDF2 100,000회)를 사용합니다. 새 기본값은 3,000,000회로 무차별 대입 공격 비용을 크게 높입니다. 업그레이드 시 데이터베이스를 다시 암호화합니다(약 1초). 업그레이드 후 5.2.0 이하 버전에서는 이 데이터베이스를 열 수 없습니다(데스크톱 스티커, MCP 인터페이스, 백업 파일은 영향 없음). 업그레이드 후 데이터베이스 잠금 해제 시 체감되는 대기 시간이 발생하며, 저사양 기기에서는 지연이 더 길어집니다. 업그레이드하시겠습니까?" },
        { "Security_Migrate_V5_Title", "데이터베이스 암호화 업그레이드" },
        { "Security_Migrate_V5_Body", "이 데이터베이스는 구형 암호화 매개변수(PBKDF2)를 사용합니다. 이번 업그레이드는 Argon2id(메모리 하드닝, 무차별 대입 비용 대폭 상승)로 전환하며 암호화 헤더에 무결성 검증과 매개변수 바인딩을 추가합니다. 업그레이드 시 데이터베이스를 다시 암호화합니다(Argon2id 계산 약 1초, 저사양 기기에서는 더 오래). 업그레이드 후 10.3 이전 버전은 이 데이터베이스를 열 수 없습니다(데이터는 손상되지 않으며 새 버전을 다시 설치하면 읽을 수 있습니다. 데스크톱 스티커, MCP 인터페이스, 백업 파일은 영향 없음). 지금 업그레이드하시겠습니까?" },
        { "Security_Migrate_Failed", "암호화 형식 업그레이드에 실패했습니다. 데이터는 변경되지 않았으며 다음 시작 시 다시 시도합니다." },
        { "Security_Migrate_Later", "나중에" },
        { "Security_Migrate_Entry", "데이터 암호화 형식 업그레이드" },
