        { "Setting_Mcp_Json", "JSON" },
        { "Setting_Mcp_DeletePermission", "삭제 마스터 스위치" },
        { "Setting_Mcp_Perm_DeleteLocked", "삭제 마스터 스위치가 꺼져 있습니다 - MCP 설정에서 켠 후 삭제 권한을 조정할 수 있습니다" },
        { "Setting_Mcp_Reset_Title", "Key 재설정" },
        { "Setting_Mcp_Reset_Message", "재설정하면 새 Key가 생성되고 기존 Key는 즉시 무효화됩니다. 구성된 Agent는 새 Key로 업데이트(재구성)해야 하지만 다시 승인받을 필요는 없습니다. 재설정하시겠습니까?" },
        { "Setting_Mcp_Reset_Confirm", "재설정" },
        { "Setting_Mcp_Copy_Title", "JSON 복사" },
        { "Setting_Mcp_Copy_Desc", "두 가지 복사 옵션이 제공됩니다:\n\n· \"JSON\": 액세스 토큰이 이미 입력된 표준 MCP 서버 구성을 복사합니다. MCP 구성에 익숙한 사용자용입니다. 복사한 후 사용 중인 Agent의 설정 파일(예: Claude Desktop의 claude_desktop_config.json, Cursor의 mcp.json)에 붙여넣으면 적용됩니다.\n\n· \"안내 문구\": Novara 소개, 설정 단계, 적용 방법, 주의 사항이 포함된 '구성 안내 + JSON'을 복사합니다. 에이전트가 대신 처리해 주길 원하는 사용자용입니다. 복사하여 에이전트에게 직접 보내면 환경을 자동으로 감지해 구성을 완료합니다." },
        { "Setting_Mcp_Copy_Hint_Short", "안내 문구" },
        { "Setting_Mcp_DeleteConfirm_Title", "삭제 권한" },
        { "Setting_Mcp_DeleteConfirm_Message", "활성화하면 에이전트가 기존 항목을 삭제할 수 있습니다. 삭제된 항목은 휴지통으로 이동하며 복원할 수 있습니다. 활성화하시겠습니까?" },
        { "Setting_Mcp_DeleteConfirm_Hint", "참고: 활성화한 후에는 MCP 설정에서 각 클라이언트의 권한 패널을 열어 삭제 열을 체크해야 삭제 권한이 실제로 적용됩니다." },
        { "Setting_Mcp_DeleteConfirm_Ok", "활성화" },
        { "Setting_Mcp_Hint", "로컬 앱 Novara를 MCP(Model Context Protocol) 서버로 구성해 주세요.\n\n【Novara란】\nNovara는 로컬 개인 지식 관리 앱으로, MCP를 통해 16개 도구(접두사 mcp__novara__)를 노출하며 메모·할 일·일기/문서·경로 백업 등 5가지 데이터를 관리합니다.\n\n【구성 내용】\n아래는 표준 MCP 서버 구성입니다. 제가 사용하는 Agent/클라이언트의 MCP 설정 파일에 병합해 주세요:\n\n{JSON}\n\n【단계】\n1. 제가 사용 중인 Agent/클라이언트를 식별하세요(Claude Desktop / Cursor / VS Code / Codex / DeepSeek Harness 등). 불확실하면 물어보세요.\n2. MCP 설정 파일을 찾아(예: Claude Desktop의 claude_desktop_config.json, Cursor의 mcp.json) 위 구성을 병합하고 JSON이 유효하도록 하세요.\n3. 클라이언트를 다시 시작하거나 다시 로드하여 구성을 적용한 뒤 새 대화를 시작하세요 - 도구 목록은 세션 시작 시 고정되므로 이 대화에서는 새 도구가 보이지 않으며, 검증은 반드시 새 대화에서 해야 합니다.\n4. 새 대화에서 mcp__novara__로 시작하는 도구가 보이는지 확인하고, 먼저 mcp__novara__get_auth_status를 호출해 승인 범위를 확인한 뒤 mcp__novara__list_items를 한 번 호출해 읽기 전용 검증을 하고 결과를 알려주세요.\n\n【주의】\n- 구성의 token은 접근 자격 증명이므로 그대로 두고 수정하거나 외부에 공유하지 마세요. 키를 대화·로그·보고서에 출력하지 마세요.\n- 아래 작업은 보안을 낮추는 동작입니다(허용 클릭 / 인터페이스 활성화 / 개인정보 잠금 해제 / 키 재설정). 제가 Novara가 맞는 앱인지 확인한 뒤 직접 수행하도록 알려주고, AI가 대신 수행하지 마세요.\n- \"미승인\" 메시지가 나오면: 제가 Novara를 열고 프롬프트에서 \"허용\"을 직접 클릭하겠습니다.\n- \"MCP 인터페이스가 비활성화됨\" 메시지가 나오면: 제가 Novara 설정에서 직접 활성화하겠습니다.\n- \"데이터베이스가 잠겨 있음\" 메시지가 나오면: 제가 Novara를 열고 개인정보 잠금 비밀번호로 직접 해제한 뒤 다시 시도하겠습니다.\n- \"액세스 토큰이 잘못됨\" 메시지가 나오면: 제가 Novara 설정의 \"MCP 인터페이스\" 카드에서 구성을 다시 생성하거나 키를 재설정하고, 설정 파일에 직접 기록하겠습니다 - 키가 대화를 거치지 않아야 합니다.\n- \"구성이 기록되었지만 적용되지 않음\" 메시지가 나오면: 도구 목록이 갱신되지 않은 것입니다. 제가 클라이언트를 재시작하고 새 대화를 시작하겠습니다.\n- \"권한이 부족함\" 메시지가 나오면: 일부 도구/유형이 승인되지 않은 것입니다(오류 메시지에 누락 항목과 승인된 항목이 나열됩니다). 제가 Novara 설정의 MCP 권한 패널에서 필요한 권한을 직접 선택하겠습니다.\n\n구성을 작성한 뒤: 제가 직접 수행해야 하는 UI 작업(다시 로드 / 허용 클릭 / 권한 선택 등)을 나열해 주세요. 제가 완료하면 새 대화를 열어 읽기 전용 검증을 한 번 실행하고 결과를 보고해 주세요." },
        { "Setting_Mcp_ExeNotFound", "이 컴퓨터에서 NovaraMCP.exe를 찾지 못했습니다(아래 구성의 command가 비어 있습니다). 소스에서 NovaraMCP를 빌드했는지 확인하거나, command를 실제 NovaraMCP.exe 전체 경로로 직접 지정하세요." },
