        { "Security_Migrate_Title", "データ暗号化形式のアップグレード" },
        { "Security_Migrate_Body", "新しいAES-256-GCM暗号化形式にアップグレードします。アップグレード後、このデータベースはNovara 3.0以降でのみ開けます。2.0に戻すとすべてのデータを読み取れなくなります。アップグレードしますか？" },
        { "Security_Migrate_Confirm", "アップグレード" },
        { "Security_Migrate_Kdf_Title", "暗号化強度のアップグレード" },
        { "Security_Migrate_Kdf_Body", "このデータベースは旧暗号化パラメータ（PBKDF2 100,000 回）を使用しています。新規定は 3,000,000 回で、ブルートフォース攻撃のコストを大幅に引き上げます。アップグレードではデータベースを再暗号化します（約 1 秒）。アップグレード後、5.2.0 以前のバージョンではこのデータベースを開けません（デスクトップ付箋・MCP インターフェース・バックアップファイルは影響なし）。アップグレード後、データベースのロック解除時に体感できる待ち時間が発生し、低スペック機では遅延が長くなります。アップグレードしますか？" },
        { "Security_Migrate_V5_Title", "データベース暗号化のアップグレード" },
        { "Security_Migrate_V5_Body", "このデータベースは旧版の暗号化パラメータ(PBKDF2)を使用しています。今回のアップグレードでは Argon2id(メモリハードニング、ブルートフォースコストを大幅に引き上げ)へ移行し、暗号化ヘッダーに整合性検証とパラメータバインディングを追加します。アップグレードではデータベースを再暗号化します(Argon2id の計算は約 1 秒、低スペック機ではより長く)。アップグレード後、10.3 以前のバージョンはこのデータベースを開けなくなります(データは破損しません。新しいバージョンを再インストールすれば読み取れます。デスクトップ付箋、MCP インターフェース、バックアップファイルは影響なし)。アップグレードしますか?" },
        { "Security_Migrate_Failed", "暗号化形式のアップグレードに失敗しました。データは変更されていません。次回起動時に再試行します。" },
