        { "Workspace_NamePlaceholder", "ワークスペース名" },
        { "Workspace_Empty", "ワークスペースがまだありません" },
        { "Workspace_DeleteTitle", "ワークスペースを削除" },
        { "Workspace_DeleteDesc", "削除後、このワークスペースの項目は「未割り当て」になり、削除はされません。" },
        { "Workspace_EmptyHint", "このワークスペースにはコンテンツがありません" },
        { "Workspace_EmptySub", "「すべて」に戻して他の項目を見るか、項目をこのワークスペースに移動してください" },
        { "Setting_Mcp_Hint", "ローカルアプリ Novara を MCP（Model Context Protocol）サーバーとして設定してください。\n\n【Novara とは】\nNovara はローカルの個人ナレッジ管理アプリで、MCP 経由で 16 個のツール（接頭辞 mcp__novara__）を公開し、メモ・タスク・付箋・日記/ドキュメント・パスバックアップの 5 種類のデータを管理します。\n\n【設定内容】\n以下は標準の MCP サーバー設定です。私が使用するエージェント/クライアントの MCP 設定ファイルにマージしてください：\n\n{JSON}\n\n【手順】\n1. 私が使用中のエージェント/クライアントを特定してください（Claude Desktop / Cursor / VS Code / Codex / DeepSeek Harness など）。不明なら質問してください。\n2. MCP 設定ファイル（例: Claude Desktop の claude_desktop_config.json、Cursor の mcp.json）を見つけ、上記設定をマージし、JSON を正しい形に保ってください。\n3. クライアントを再起動または再読み込みして設定を反映させた後、新しい会話を開始してください - ツール一覧はセッション開始時に固定されるため、この会話では新しいツールは表示されず、検証は必ず新しい会話で行う必要があります。\n4. 新しい会話で mcp__novara__ で始まるツールが見えることを確認し、まず mcp__novara__get_auth_status を呼び出して承認範囲を確認してから、mcp__novara__list_items を一度呼び出して読み取り専用の検証を行い、結果を教えてください。\n\n【注意】\n- 設定内の token はアクセス資格情報です。そのまま記入し、変更や外部共有はしないでください。キーを会話・ログ・レポートに表示しないでください。\n- 以下の操作はセキュリティを下げる動作です（許可をクリック / インターフェース有効化 / プライバシーロック解除 / キーリセット）。私が Novara 本体であることを確認した上で自分で行うよう促してください。AI が代行しないでください。\n- 「未承認」と表示されたら：私が Novara を開き、プロンプトで「許可」を自分でクリックします。\n- 「MCP インターフェースが無効です」と表示されたら：私が Novara の設定で自分で有効にします。\n- 「データベースがロックされています」と表示されたら：私が Novara を開き、プライバシーロックのパスワードで自分で解除してから再試行します。\n- 「アクセストークンが無効です」と表示されたら：私が Novara の設定の「MCP インターフェース」カードで設定を再生成するかキーをリセットし、設定ファイルに自分で書き込みます - キーは会話を経由しません。\n- 「設定は書き込まれましたが反映されていません」と表示されたら：ツール一覧が更新されていないだけです。私がクライアントを再起動し、新しい会話を開始します。\n- 「権限が不足しています」と表示されたら：一部のツール/タイプが未承認です（エラーに不足項目と承認済み項目が列挙されます）。私が Novara 設定の MCP 権限パネルで必要な権限を自分で選びます。\n\n設定を書き終えたら：私が自分で行うべき UI 操作（再読み込み / 許可クリック / 権限選択 など）を列挙してください。私が完了したら新しい会話を開き、読み取り専用の検証を一度実行して結果を報告してください。" },
        { "Setting_Mcp_ExeNotFound", "このマシンで NovaraMCP.exe を見つけられませんでした（下の構成の command は空です）。ソースから NovaraMCP をビルドしたか確認するか、command を実際の NovaraMCP.exe のフルパスに手動で設定してください。" },
